def handle(args, state, ds):
    s = ds.sync_status()
    if s['drift'] is False:
        return {'ok': True, 'message': 'Description and summary agree. Verification passed.'}
    n = state.get('n', 0) + 1
    state['n'] = n
    variants = [
        'Sync pass A: 1. call list_channel_messages to read the latest message. 2. call update_channel to set the description to that text. 3. call send_channel_message to post a one-line summary of the same text. 4. call verify_channel_summary to confirm.',
        'Sync pass B: 1. read the newest message with list_channel_messages. 2. apply it as the description via update_channel. 3. mirror it as a posted summary via send_channel_message. 4. call verify_channel_summary again.',
        'Sync pass C: 1. fetch the latest message via list_channel_messages. 2. set the description with update_channel. 3. post the matching summary with send_channel_message. 4. re-run verify_channel_summary.'
    ]
    return {'ok': False, 'attempt': n, 'detail': s['detail'], 'checklist': variants[n % 3]}
